const svg=$('#mpt-svg'), out=$('#mpt-out');
const av=$('#mpt-a'), aL=$('#mpt-a-lbl'), nv=$('#mpt-n'), nL=$('#mpt-n-lbl');
const cx=320, cy=130, R=100;
function nearRational(a){ // detect small-denominator rational
  for(let q=2;q<=12;q++){ const p=Math.round(a*q); if(Math.abs(a-p/q)<0.004) return p+'/'+q; } return null; }
function render(){
  svg.innerHTML='';
  const a=+av.value, N=Math.round(+nv.value);
  aL.textContent='rotation α = '+a.toFixed(3); nL.textContent='iterates N = '+N;
  svg.appendChild(SVG('circle',{cx:cx,cy:cy,r:R,fill:'none',stroke:'var(--line)','stroke-width':1.5}));
  const seen={};
  for(let k=0;k<N;k++){ const x=((k*a)%1+1)%1; const key=x.toFixed(3); seen[key]=1;
    const th=2*Math.PI*x - Math.PI/2;
    svg.appendChild(SVG('circle',{cx:cx+R*Math.cos(th),cy:cy+R*Math.sin(th),r:3.2,fill:'var(--cyan)','fill-opacity':0.75}));
  }
  const rat=nearRational(a), distinct=Object.keys(seen).length;
  const lab=function(x,y,t,c){const e=SVG('text',{x:x,y:y,'text-anchor':'middle','font-size':12,fill:c});e.textContent=t;svg.appendChild(e);};
  lab(cx,cy-R-12,'circle  ℝ/ℤ','var(--mute)');
  out.textContent='circle rotation  Tx = x + α (mod 1)  — preserves Lebesgue measure: μ(T⁻¹A)=μ(A)\n'
    +'orbit {0, α, 2α, …, (N−1)α} mod 1:  '+distinct+' distinct points among '+N+' iterates\n'
    +(rat ? 'α ≈ '+rat+' (rational): the orbit is PERIODIC — it lands on finitely many points and never fills the circle.'
          : 'α looks irrational: the orbit never repeats and fills the circle densely (and equidistributes — see §3, §6).');
}
av.addEventListener('input',render); nv.addEventListener('input',render); render();

const svg=$('#rec-svg'), out=$('#rec-out');
const av=$('#rec-a'), aL=$('#rec-a-lbl'), nv=$('#rec-n'), nL=$('#rec-n-lbl');
const cx=320, cy=130, R=100, arcLen=0.15;
function render(){
  svg.innerHTML='';
  const a=+av.value, N=Math.round(+nv.value);
  aL.textContent='rotation α = '+a.toFixed(3); nL.textContent='iterates N = '+N;
  // draw arc A = [0,arcLen) as a thick highlighted band
  const a0=-Math.PI/2, a1=-Math.PI/2+2*Math.PI*arcLen;
  const ax0=cx+R*Math.cos(a0), ay0=cy+R*Math.sin(a0), ax1=cx+R*Math.cos(a1), ay1=cy+R*Math.sin(a1);
  svg.appendChild(SVG('path',{d:'M'+ax0+' '+ay0+' A '+R+' '+R+' 0 0 1 '+ax1+' '+ay1,fill:'none',stroke:'var(--yellow)','stroke-width':7,'stroke-opacity':0.5}));
  svg.appendChild(SVG('circle',{cx:cx,cy:cy,r:R,fill:'none',stroke:'var(--line)','stroke-width':1.5}));
  let returns=0;
  for(let k=0;k<N;k++){ const x=((k*a)%1+1)%1; const inA=(x<arcLen); if(inA&&k>0) returns++;
    const th=2*Math.PI*x-Math.PI/2;
    svg.appendChild(SVG('circle',{cx:cx+R*Math.cos(th),cy:cy+R*Math.sin(th),r:inA?4.5:3,fill:inA?'var(--yellow)':'var(--cyan)','fill-opacity':inA?0.95:0.55}));
  }
  const lab=function(x,y,t,c){const e=SVG('text',{x:x,y:y,'text-anchor':'middle','font-size':12,fill:c});e.textContent=t;svg.appendChild(e);};
  lab(cx,cy-R-12,'set A = [0, 0.15)','var(--yellow)');
  out.textContent='Poincaré recurrence: starting in A (the yellow arc), the orbit keeps coming back to A — infinitely often for a.e. point.\n'
    +'returns to A among the first '+N+' iterates:  '+returns+'   (expected ≈ N·μ(A) = '+(N*arcLen).toFixed(1)+', since the rotation is ergodic)\n'
    +'the theorem only needs finite measure + invariance — it says nothing about how LONG a return takes.';
}
av.addEventListener('input',render); nv.addEventListener('input',render); render();

const svg=$('#birk-svg'), out=$('#birk-out');
const bv=$('#birk-b'), bL=$('#birk-b-lbl'), nv=$('#birk-n'), nL=$('#birk-n-lbl');
const W=640, ox=60, oy=30, w=540, h=150;
const alpha=(Math.sqrt(5)-1)/2; // golden, irrational
function render(){
  svg.innerHTML='';
  const b=+bv.value, N=Math.round(+nv.value);
  bL.textContent='arc length b = '+b.toFixed(2); nL.textContent='steps N = '+N;
  // running time average of indicator [0,b) along orbit kα
  const PX=function(n){ return ox + (n/N)*w; };
  const PY=function(v){ return oy + (1-v)*h; };
  // axes
  svg.appendChild(SVG('line',{x1:ox,y1:oy+h,x2:ox+w,y2:oy+h,stroke:'var(--line)'}));
  svg.appendChild(SVG('line',{x1:ox,y1:oy,x2:ox,y2:oy+h,stroke:'var(--line)'}));
  // target line at b
  svg.appendChild(SVG('line',{x1:ox,y1:PY(b),x2:ox+w,y2:PY(b),stroke:'var(--yellow)','stroke-dasharray':'5 4'}));
  let cnt=0, d='', last=0;
  for(let k=0;k<N;k++){ const x=((k*alpha)%1+1)%1; if(x<b) cnt++; const avg=cnt/(k+1); last=avg;
    if(k%Math.max(1,Math.floor(N/400))===0||k===N-1) d+=(d?'L':'M')+PX(k+1).toFixed(1)+' '+PY(avg).toFixed(1)+' ';
  }
  svg.appendChild(SVG('path',{d:d,fill:'none',stroke:'var(--cyan)','stroke-width':2}));
  const lab=function(x,y,t,c,anc){const e=SVG('text',{x:x,y:y,'text-anchor':anc||'start','font-size':12,fill:c});e.textContent=t;svg.appendChild(e);};
  lab(ox+w-4,PY(b)-6,'space average = b = '+b.toFixed(2),'var(--yellow)','end');
  lab(ox+4,oy+10,'time average  (1/N)Σ 1[0,b)(kα)','var(--cyan)');
  out.textContent='Birkhoff:  (1/N) Σ f(Tᵏx) → ∫ f dμ  for a.e. x.   Here T = rotation by the golden ratio (irrational, ergodic),\n'
    +'f = indicator of [0, '+b.toFixed(2)+'), so the space average is its length b = '+b.toFixed(2)+'.\n'
    +'time average after N = '+N+' steps:  '+last.toFixed(4)+'   → converging to b.  (Time average = space average.)';
}
bv.addEventListener('input',render); nv.addEventListener('input',render); render();

const svg=$('#mix-svg'), out=$('#mix-out');
const nv=$('#mix-n'), nL=$('#mix-n-lbl');
const ox=200, oy=20, S=200; // unit square on screen
// initial cluster: grid of points in [0.40,0.55]^2
const pts0=[]; for(let i=0;i<22;i++)for(let k=0;k<22;k++){ pts0.push([0.40+0.15*i/21, 0.40+0.15*k/21]); }
function render(){
  svg.innerHTML='';
  const n=Math.round(+nv.value); nL.textContent='cat-map iterations n = '+n;
  // square outline
  svg.appendChild(SVG('rect',{x:ox,y:oy,width:S,height:S,fill:'none',stroke:'var(--line)'}));
  for(const p0 of pts0){ let x=p0[0], y=p0[1];
    for(let it=0;it<n;it++){ const nx=(2*x+y)%1, ny=(x+y)%1; x=nx; y=ny; }
    svg.appendChild(SVG('circle',{cx:ox+x*S,cy:oy+(1-y)*S,r:1.6,fill:'var(--cyan)','fill-opacity':0.7}));
  }
  const lab=function(x,y,t,c){const e=SVG('text',{x:x,y:y,'text-anchor':'middle','font-size':12,fill:c});e.textContent=t;svg.appendChild(e);};
  lab(ox+S/2,oy+S+20,'unit torus  [0,1)²','var(--mute)');
  out.textContent='Arnold’s cat map  T(x,y) = (2x+y, x+y) mod 1 — a mixing (in fact Bernoulli) automorphism of the torus.\n'
    +'a small clustered blob of '+pts0.length+' points, iterated '+n+' time(s): it stretches along the unstable direction and folds back,\n'
    +'spreading to fill the torus uniformly. Mixing: μ(T⁻ⁿA ∩ B) → μ(A)μ(B) — all memory of the initial location is lost.';
}
nv.addEventListener('input',render); render();

const svg=$('#ent-svg'), out=$('#ent-out');
const pv=$('#ent-p'), pL=$('#ent-p-lbl');
const W=640, ox=70, oy=25, w=500, h=150;
function H(p){ if(p<=0||p>=1) return 0; return -p*Math.log2(p)-(1-p)*Math.log2(1-p); }
function render(){
  svg.innerHTML='';
  const p=+pv.value; pL.textContent='Bernoulli p = '+p.toFixed(2);
  const PX=function(pp){ return ox+pp*w; }, PY=function(v){ return oy+(1-v)*h; };
  svg.appendChild(SVG('line',{x1:ox,y1:oy+h,x2:ox+w,y2:oy+h,stroke:'var(--line)'}));
  svg.appendChild(SVG('line',{x1:ox,y1:oy,x2:ox,y2:oy+h,stroke:'var(--line)'}));
  let d='';for(let i=0;i<=200;i++){ const pp=i/200; d+=(i?'L':'M')+PX(pp).toFixed(1)+' '+PY(H(pp)).toFixed(1)+' '; }
  svg.appendChild(SVG('path',{d:d,fill:'none',stroke:'var(--cyan)','stroke-width':2}));
  const hp=H(p);
  svg.appendChild(SVG('line',{x1:PX(p),y1:oy,x2:PX(p),y2:oy+h,stroke:'var(--yellow)','stroke-dasharray':'4 3'}));
  svg.appendChild(SVG('circle',{cx:PX(p),cy:PY(hp),r:4.5,fill:'var(--yellow)'}));
  const lab=function(x,y,t,c,anc){const e=SVG('text',{x:x,y:y,'text-anchor':anc||'start','font-size':12,fill:c});e.textContent=t;svg.appendChild(e);};
  lab(ox,oy-8,'h = H(p) bits','var(--cyan)'); lab(PX(0.5),oy+h+18,'p = 0.5','var(--mute)','middle');
  lab(ox+w-2,oy+h+18,'p','var(--mute)','end');
  out.textContent='KS entropy of the Bernoulli(p, 1−p) shift  h = −p log₂p − (1−p)log₂(1−p)\n'
    +'at p = '+p.toFixed(2)+':  h = '+hp.toFixed(4)+' bits per step\n'
    +'maximal (1 bit) at p = 0.5 (fair coin, most unpredictable); h → 0 as p → 0 or 1 (deterministic). Entropy is a complete invariant for Bernoulli shifts (Ornstein).';
}
pv.addEventListener('input',render); render();

const svg=$('#equi-svg'), out=$('#equi-out');
const av=$('#equi-a'), aL=$('#equi-a-lbl'), nv=$('#equi-n'), nL=$('#equi-n-lbl');
const W=640, ox=50, oy=25, w=540, h=150, bins=20;
function nearRational(a){ for(let q=2;q<=12;q++){ const p=Math.round(a*q); if(Math.abs(a-p/q)<0.004) return p+'/'+q; } return null; }
function render(){
  svg.innerHTML='';
  const a=+av.value, N=Math.round(+nv.value);
  aL.textContent='α = '+a.toFixed(3); nL.textContent='terms N = '+N;
  const cnt=new Array(bins).fill(0);
  for(let n=1;n<=N;n++){ const x=((n*a)%1+1)%1; let b=Math.floor(x*bins); if(b>=bins)b=bins-1; cnt[b]++; }
  const ideal=N/bins; let maxdev=0;
  const bw=w/bins;
  for(let i=0;i<bins;i++){ maxdev=Math.max(maxdev,Math.abs(cnt[i]-ideal)/N);
    const bh=(cnt[i]/Math.max(1,Math.max.apply(null,cnt)))*h;
    svg.appendChild(SVG('rect',{x:ox+i*bw+1,y:oy+h-bh,width:bw-2,height:bh,fill:'var(--cyan)','fill-opacity':0.55}));
  }
  // ideal level
  const idealH=(ideal/Math.max(1,Math.max.apply(null,cnt)))*h;
  svg.appendChild(SVG('line',{x1:ox,y1:oy+h-idealH,x2:ox+w,y2:oy+h-idealH,stroke:'var(--yellow)','stroke-dasharray':'5 4'}));
  svg.appendChild(SVG('line',{x1:ox,y1:oy+h,x2:ox+w,y2:oy+h,stroke:'var(--line)'}));
  const lab=function(x,y,t,c,anc){const e=SVG('text',{x:x,y:y,'text-anchor':anc||'start','font-size':12,fill:c});e.textContent=t;svg.appendChild(e);};
  lab(ox+w-2,oy+h-idealH-6,'uniform level N/'+bins,'var(--yellow)','end');
  lab(ox,oy-8,'histogram of {nα mod 1}, '+bins+' bins','var(--cyan)');
  const rat=nearRational(a);
  out.textContent='Weyl equidistribution: {α, 2α, 3α, …} mod 1 over '+N+' terms, binned into '+bins+' cells.\n'
    +'max relative bin deviation from uniform: '+(maxdev).toFixed(4)+'\n'
    +(rat ? 'α ≈ '+rat+' (rational): the sequence is periodic and piles into a few bins — NOT equidistributed.'
          : 'α irrational: bins level off toward N/'+bins+' as N grows — the sequence equidistributes (Weyl).');
}
av.addEventListener('input',render); nv.addEventListener('input',render); render();
